    int day, closed = 0;
    while (scanf("%d", &day) == 1) {
        if (is_holiday(day)) {
            printf("день %d: выходной\n", day);
            closed++;
        } else {
            printf("день %d: рабочий\n", day);
        }
    }
    printf("выходных: %d\n", closed);
    return 0;
}

